    if (root.querySelectorAll) {
      root.querySelectorAll('[data-arm-on-load][disabled]').forEach(function (b) {
        b.disabled = false;
        b.removeAttribute('title');
      });
    }
  }
  document.body.addEventListener('htmx:load', function (e) {
    if (e.target) arm(e.target);
